reference_solution:
def valid_number(s):
    digit_seen = dot_seen = exponent_seen = False
    for index, char in enumerate(s):
        if "0" <= char <= "9":
            digit_seen = True
        elif char in "+-":
            if index != 0 and s[index - 1] not in "eE":
                return False
        elif char == ".":
            if dot_seen or exponent_seen:
                return False
            dot_seen = True
        elif char in "eE":
            if exponent_seen or not digit_seen:
                return False
            exponent_seen = True
            digit_seen = False
        else:
            return False
    return digit_seen

